import { randomUUID } from 'node:crypto';
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
import { dirname } from 'node:path';

const MAX_TITLE = 300;
const MAX_AUTHOR = 200;
const MAX_NOTES = 20000;

export class ValidationError extends Error {}

function trim(value, max) {
  if (typeof value !== 'string') return '';
  return value.trim().slice(0, max);
}

function newId(taken) {
  let id;
  do {
    id = randomUUID().slice(0, 8);
  } while (taken.has(id));
  return id;
}

/**
 * Books live in a single JSON file. The whole list is held in memory (it is a
 * personal reading list, not a dataset) and rewritten on every change.
 */
export async function createStore(filePath, { now = () => new Date() } = {}) {
  const books = await read(filePath);
  let writes = Promise.resolve();

  // Serialise writes so two overlapping requests cannot interleave a
  // read-modify-write and lose one of the changes.
  function persist() {
    const snapshot = JSON.stringify({ books }, null, 2);
    writes = writes.then(
      () => write(filePath, snapshot),
      () => write(filePath, snapshot),
    );
    return writes;
  }

  return {
    list() {
      const reading = books.filter((b) => !b.finishedAt);
      const finished = books.filter((b) => b.finishedAt);
      reading.sort((a, b) => b.addedAt.localeCompare(a.addedAt));
      finished.sort((a, b) => b.finishedAt.localeCompare(a.finishedAt));
      return { reading, finished };
    },

    get(id) {
      return books.find((b) => b.id === id) ?? null;
    },

    async add({ title, author, notes }) {
      const cleanTitle = trim(title, MAX_TITLE);
      if (!cleanTitle) throw new ValidationError('A title is required.');

      const book = {
        id: newId(new Set(books.map((b) => b.id))),
        title: cleanTitle,
        author: trim(author, MAX_AUTHOR),
        notes: trim(notes, MAX_NOTES),
        addedAt: now().toISOString(),
        finishedAt: null,
      };
      books.push(book);
      await persist();
      return book;
    },

    async finish(id) {
      const book = this.get(id);
      if (!book) return null;
      if (!book.finishedAt) {
        book.finishedAt = now().toISOString();
        await persist();
      }
      return book;
    },

    async setNotes(id, notes) {
      const book = this.get(id);
      if (!book) return null;
      book.notes = trim(notes, MAX_NOTES);
      await persist();
      return book;
    },
  };
}

async function read(filePath) {
  let raw;
  try {
    raw = await readFile(filePath, 'utf8');
  } catch (err) {
    if (err.code === 'ENOENT') return []; // first run
    throw err;
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new Error(`${filePath} is not valid JSON. Fix or remove it, then restart.`);
  }

  const list = Array.isArray(parsed) ? parsed : parsed?.books;
  if (!Array.isArray(list)) return [];

  return list.filter((b) => b && typeof b.id === 'string' && typeof b.title === 'string').map((b) => ({
    id: b.id,
    title: b.title,
    author: typeof b.author === 'string' ? b.author : '',
    notes: typeof b.notes === 'string' ? b.notes : '',
    addedAt: typeof b.addedAt === 'string' ? b.addedAt : new Date(0).toISOString(),
    finishedAt: typeof b.finishedAt === 'string' ? b.finishedAt : null,
  }));
}

// Write to a temp file and rename, so an interrupted write cannot truncate the
// existing list.
async function write(filePath, contents) {
  await mkdir(dirname(filePath), { recursive: true });
  const tmp = `${filePath}.${process.pid}.tmp`;
  await writeFile(tmp, contents, 'utf8');
  await rename(tmp, filePath);
}

