const ESCAPES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };

/** Everything user-typed goes through this before reaching the page. */
export function escape(value) {
  return String(value ?? '').replace(/[&<>"']/g, (c) => ESCAPES[c]);
}

function formatDate(iso) {
  const date = new Date(iso);
  if (Number.isNaN(date.getTime())) return '';
  return date.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
}

function layout(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escape(title)}</title>
<style>${CSS}</style>
</head>
<body>
<main>
${body}
</main>
</body>
</html>
`;
}

function byline(book) {
  return book.author
    ? `<span class="author">${escape(book.author)}</span>`
    : `<span class="author muted">Unknown author</span>`;
}

function readingItem(book) {
  return `<li>
  <div class="row">
    <div>
      <a class="title" href="/books/${escape(book.id)}">${escape(book.title)}</a>
      ${byline(book)}
    </div>
    <form method="post" action="/books/${escape(book.id)}/finish">
      <input type="hidden" name="from" value="/">
      <button type="submit">Mark finished</button>
    </form>
  </div>
</li>`;
}

function finishedItem(book) {
  return `<li>
  <div class="row">
    <div>
      <a class="title" href="/books/${escape(book.id)}">${escape(book.title)}</a>
      ${byline(book)}
    </div>
    <span class="muted date">Finished ${escape(formatDate(book.finishedAt))}</span>
  </div>
</li>`;
}

export function homePage({ reading, finished, error = null, draft = {} }) {
  const body = `
<h1>Bookshelf</h1>

<section>
  <h2>Currently reading <span class="count">${reading.length}</span></h2>
  ${
    reading.length
      ? `<ul class="books">${reading.map(readingItem).join('\n')}</ul>`
      : `<p class="muted empty">Nothing on the go. Add a book below.</p>`
  }
</section>

<section>
  <h2>Finished <span class="count">${finished.length}</span></h2>
  ${
    finished.length
      ? `<ul class="books">${finished.map(finishedItem).join('\n')}</ul>`
      : `<p class="muted empty">No finished books yet.</p>`
  }
</section>

<section class="add">
  <h2>Add a book</h2>
  ${error ? `<p class="error" role="alert">${escape(error)}</p>` : ''}
  <form method="post" action="/books">
    <label for="title">Title</label>
    <input id="title" name="title" value="${escape(draft.title)}" required autocomplete="off">

    <label for="author">Author <span class="muted">(optional)</span></label>
    <input id="author" name="author" value="${escape(draft.author)}" autocomplete="off">

    <label for="notes">Notes <span class="muted">(optional)</span></label>
    <textarea id="notes" name="notes" rows="3">${escape(draft.notes)}</textarea>

    <button type="submit">Add book</button>
  </form>
</section>
`;
  return layout('Bookshelf', body);
}

export function bookPage(book, { saved = false } = {}) {
  const status = book.finishedAt
    ? `<p class="status done">Finished ${escape(formatDate(book.finishedAt))}</p>`
    : `<form method="post" action="/books/${escape(book.id)}/finish">
    <input type="hidden" name="from" value="/books/${escape(book.id)}">
    <button type="submit">Mark finished</button>
  </form>`;

  const body = `
<p><a class="back" href="/">&larr; All books</a></p>

<h1>${escape(book.title)}</h1>
<p class="byline">${byline(book)}</p>

<p class="muted date">Added ${escape(formatDate(book.addedAt))}</p>
${status}

<section class="notes">
  <h2>Notes</h2>
  ${saved ? `<p class="saved" role="status">Notes saved.</p>` : ''}
  <form method="post" action="/books/${escape(book.id)}/notes">
    <textarea name="notes" rows="10" aria-label="Notes">${escape(book.notes)}</textarea>
    <button type="submit">Save notes</button>
  </form>
</section>
`;
  return layout(`${book.title} — Bookshelf`, body);
}

export function errorPage(status, message) {
  return layout(message, `
<h1>${escape(message)}</h1>
<p><a class="back" href="/">&larr; All books</a></p>
`);
}

const CSS = `
:root {
  --bg: #fbfaf7;
  --panel: #fff;
  --ink: #1d1c1a;
  --muted: #6b6862;
  --line: #e4e0d8;
  --accent: #7a5c34;
  --error: #a3312a;
}
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #171614;
    --panel: #201e1b;
    --ink: #ece9e3;
    --muted: #9b968d;
    --line: #332f2a;
    --accent: #d8b48a;
    --error: #eb8b84;
  }
}
