h2 {
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.09em;
  color: var(--muted);
  font-family: ui-sans-serif, system-ui, sans-serif;
  margin: 0 0 0.75rem;
}
.count {
  font-family: inherit;
  letter-spacing: 0;
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 0 0.45rem;
  margin-left: 0.35rem;
}
section { margin-bottom: 2.25rem; }
.muted { color: var(--muted); }
.empty { margin: 0; font-style: italic; }
ul.books { list-style: none; margin: 0; padding: 0; }
ul.books li {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 0.8rem 1rem;
  margin-bottom: 0.5rem;
}
.row { display: flex; align-items: center; justify-content: space-between; gap: 1rem; }
.row > div { min-width: 0; }
.title {
  display: block;
  color: var(--ink);
  text-decoration: none;
  font-size: 1.05rem;
  border-bottom: 1px solid transparent;
}
.title:hover { border-bottom-color: var(--accent); }
.author { display: block; font-size: 0.9rem; color: var(--muted); }
.byline { margin: -1.25rem 0 1.25rem; font-size: 1rem; }
.byline .author { font-size: 1rem; }
.date { font-size: 0.85rem; white-space: nowrap; }
.status { font-family: ui-sans-serif, system-ui, sans-serif; font-size: 0.9rem; }
.status.done { color: var(--accent); }
label {
  display: block;
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.82rem;
  margin: 0.9rem 0 0.3rem;
}
input, textarea {
  width: 100%;
  font: inherit;
  color: var(--ink);
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 0.5rem 0.65rem;
}
textarea { resize: vertical; }
input:focus, textarea:focus { outline: 2px solid var(--accent); outline-offset: 1px; }
button {
  font-family: ui-sans-serif, system-ui, sans-serif;
  font-size: 0.85rem;
  margin-top: 1rem;
  padding: 0.45rem 0.9rem;
  color: var(--bg);
  background: var(--ink);
  border: 1px solid var(--ink);
  border-radius: 6px;
  cursor: pointer;
  white-space: nowrap;
}
button:hover { background: var(--accent); border-color: var(--accent); }
.row button { margin-top: 0; background: none; color: var(--muted); border-color: var(--line); }
.row button:hover { color: var(--bg); }
.error { color: var(--error); margin: 0; font-size: 0.9rem; }
.saved { color: var(--accent); font-size: 0.9rem; margin: 0 0 0.5rem; }
.back { color: var(--muted); text-decoration: none; font-size: 0.9rem; }
.back:hover { color: var(--accent); }
`;

