import { createServer } from 'node:http';

import { createStore, ValidationError } from './store.js';
import { bookPage, errorPage, homePage } from './views.js';

const MAX_BODY = 64 * 1024;

function send(res, status, html) {
  res.writeHead(status, {
    'content-type': 'text/html; charset=utf-8',
    'content-length': Buffer.byteLength(html),
    'cache-control': 'no-store',
  });
  res.end(html);
}

function redirect(res, location) {
  // 303 so the browser follows up with a GET and a reload does not re-submit.
  res.writeHead(303, { location, 'cache-control': 'no-store' });
  res.end();
}

async function readForm(req) {
  let size = 0;
  const chunks = [];
  for await (const chunk of req) {
    size += chunk.length;
    if (size > MAX_BODY) {
      const err = new Error('Request body too large');
      err.status = 413;
      throw err;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

/** Only allow redirects back into this app, never to an attacker-supplied host. */
function safePath(value, fallback) {
  return typeof value === 'string' && /^\/[\w\-/]*$/.test(value) ? value : fallback;
}

export function createApp(store) {
  return async function handle(req, res) {
    const url = new URL(req.url, 'http://localhost');
    const path = url.pathname.replace(/\/+$/, '') || '/';
    const method = req.method === 'HEAD' ? 'GET' : req.method;

    if (path === '/' && method === 'GET') {
      const { reading, finished } = store.list();
      return send(res, 200, homePage({ reading, finished }));
    }

    if (path === '/books' && method === 'POST') {
      const form = await readForm(req);
      try {
        const book = await store.add({
          title: form.get('title'),
          author: form.get('author'),
          notes: form.get('notes'),
        });
        return redirect(res, `/books/${book.id}`);
      } catch (err) {
        if (!(err instanceof ValidationError)) throw err;
        const { reading, finished } = store.list();
        return send(res, 400, homePage({
          reading,
          finished,
          error: err.message,
          draft: {
            title: form.get('title'),
            author: form.get('author'),
            notes: form.get('notes'),
          },
        }));
      }
    }

    const book = path.match(/^\/books\/([\w-]+)$/);
    if (book && method === 'GET') {
      const found = store.get(book[1]);
      if (!found) return send(res, 404, errorPage(404, 'No such book'));
      return send(res, 200, bookPage(found, { saved: url.searchParams.has('saved') }));
    }

    const finish = path.match(/^\/books\/([\w-]+)\/finish$/);
    if (finish && method === 'POST') {
      const form = await readForm(req);
      const updated = await store.finish(finish[1]);
      if (!updated) return send(res, 404, errorPage(404, 'No such book'));
      return redirect(res, safePath(form.get('from'), `/books/${updated.id}`));
    }

    const notes = path.match(/^\/books\/([\w-]+)\/notes$/);
    if (notes && method === 'POST') {
      const form = await readForm(req);
      const updated = await store.setNotes(notes[1], form.get('notes') ?? '');
      if (!updated) return send(res, 404, errorPage(404, 'No such book'));
      return redirect(res, `/books/${updated.id}?saved=1`);
    }

    return send(res, 404, errorPage(404, 'Page not found'));
  };
}

export async function createBookshelf(dataFile) {
  const store = await createStore(dataFile);
  const handle = createApp(store);

  const server = createServer((req, res) => {
    handle(req, res).catch((err) => {
      const status = err.status ?? 500;
      if (status === 500) console.error(err);
      if (!res.headersSent) {
        send(res, status, errorPage(status, status === 500 ? 'Something went wrong' : err.message));
      } else {
        res.end();
      }
    });
  });

  return { server, store };
}

