import { mkdtemp, readFile, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { beforeEach, describe, expect, it } from 'vitest';

import { createStore, ValidationError } from '../src/store.js';

let file;

beforeEach(async () => {
  file = join(await mkdtemp(join(tmpdir(), 'bookshelf-')), 'books.json');
});

describe('createStore', () => {
  it('starts empty when the file does not exist yet', async () => {
    const store = await createStore(file);
    expect(store.list()).toEqual({ reading: [], finished: [] });
  });

  it('adds a book as currently reading and gives it an id', async () => {
    const store = await createStore(file);
    const book = await store.add({ title: 'Dune', author: 'Frank Herbert', notes: 'spice' });

    expect(book.id).toMatch(/^[\w-]+$/);
    expect(book.finishedAt).toBeNull();
    expect(store.list().reading).toEqual([book]);
    expect(store.get(book.id)).toEqual(book);
  });

  it('trims whitespace and rejects a blank title', async () => {
    const store = await createStore(file);

    const book = await store.add({ title: '  Dune  ', author: '  Herbert  ' });
    expect(book).toMatchObject({ title: 'Dune', author: 'Herbert', notes: '' });

    await expect(store.add({ title: '   ' })).rejects.toThrow(ValidationError);
    await expect(store.add({ title: undefined })).rejects.toThrow(ValidationError);
    expect(store.list().reading).toHaveLength(1);
  });

  it('moves a book to finished and records when', async () => {
    const store = await createStore(file, { now: () => new Date('2026-03-04T10:00:00Z') });
    const book = await store.add({ title: 'Dune' });

    await store.finish(book.id);

    const { reading, finished } = store.list();
    expect(reading).toEqual([]);
    expect(finished).toHaveLength(1);
    expect(finished[0].finishedAt).toBe('2026-03-04T10:00:00.000Z');
  });

  it('keeps the original finish date if marked finished twice', async () => {
    let clock = new Date('2026-03-04T10:00:00Z');
    const store = await createStore(file, { now: () => clock });
    const book = await store.add({ title: 'Dune' });

    await store.finish(book.id);
    clock = new Date('2026-05-05T10:00:00Z');
    await store.finish(book.id);

    expect(store.get(book.id).finishedAt).toBe('2026-03-04T10:00:00.000Z');
  });

  it('returns null for an unknown book instead of throwing', async () => {
    const store = await createStore(file);
    expect(store.get('nope')).toBeNull();
    expect(await store.finish('nope')).toBeNull();
    expect(await store.setNotes('nope', 'hi')).toBeNull();
  });

  it('updates notes', async () => {
    const store = await createStore(file);
    const book = await store.add({ title: 'Dune' });

    await store.setNotes(book.id, '  Reread of a favourite.  ');

    expect(store.get(book.id).notes).toBe('Reread of a favourite.');
  });

  it('sorts newest-added first and most-recently-finished first', async () => {
    let clock = new Date('2026-01-01T00:00:00Z');
    const store = await createStore(file, { now: () => clock });

    const a = await store.add({ title: 'A' });
    clock = new Date('2026-01-02T00:00:00Z');
    const b = await store.add({ title: 'B' });
    clock = new Date('2026-01-03T00:00:00Z');
    const c = await store.add({ title: 'C' });

    expect(store.list().reading.map((x) => x.title)).toEqual(['C', 'B', 'A']);

    clock = new Date('2026-02-01T00:00:00Z');
    await store.finish(a.id);
    clock = new Date('2026-02-02T00:00:00Z');
    await store.finish(c.id);

    expect(store.list().finished.map((x) => x.title)).toEqual(['C', 'A']);
    expect(store.list().reading.map((x) => x.title)).toEqual([b.title]);
  });

  it('survives a restart by reloading the JSON file', async () => {
    const first = await createStore(file);
    const book = await first.add({ title: 'Dune', author: 'Frank Herbert', notes: 'spice' });
    await first.finish(book.id);

    const second = await createStore(file);
    expect(second.list().finished).toEqual([book]);
    expect(second.get(book.id).notes).toBe('spice');
  });

  it('writes readable JSON', async () => {
    const store = await createStore(file);
    await store.add({ title: 'Dune' });

    const parsed = JSON.parse(await readFile(file, 'utf8'));
    expect(parsed.books).toHaveLength(1);
    expect(parsed.books[0].title).toBe('Dune');
  });

  it('does not lose changes when writes overlap', async () => {
    const store = await createStore(file);
    await Promise.all(
      Array.from({ length: 20 }, (_, i) => store.add({ title: `Book ${i}` })),
    );

    const reloaded = await createStore(file);
    expect(reloaded.list().reading).toHaveLength(20);
  });

  it('skips malformed entries but keeps the good ones', async () => {
    await writeFile(
      file,
      JSON.stringify({ books: [{ id: 'ok', title: 'Kept' }, { title: 'no id' }, null, 7] }),
    );

    const store = await createStore(file);
    const { reading } = store.list();
    expect(reading).toHaveLength(1);
    expect(reading[0]).toMatchObject({ id: 'ok', title: 'Kept', author: '', notes: '' });
  });

  it('refuses to start on an unparseable file rather than wiping it', async () => {
    await writeFile(file, '{ this is not json');
    await expect(createStore(file)).rejects.toThrow(/not valid JSON/);
    expect(await readFile(file, 'utf8')).toBe('{ this is not json');
  });
});

