import { mkdtemp } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { createBookshelf } from '../src/app.js';

let base;
let server;
let store;

beforeEach(async () => {
  const file = join(await mkdtemp(join(tmpdir(), 'bookshelf-')), 'books.json');
  ({ server, store } = await createBookshelf(file));
  await new Promise((done) => server.listen(0, '127.0.0.1', done));
  base = `http://127.0.0.1:${server.address().port}`;
});

afterEach(async () => {
  await new Promise((done) => server.close(done));
});

const form = (fields) => ({
  method: 'POST',
  headers: { 'content-type': 'application/x-www-form-urlencoded' },
  body: new URLSearchParams(fields),
  redirect: 'manual',
});

async function addBook(fields) {
  const res = await fetch(`${base}/books`, form(fields));
  expect(res.status).toBe(303);
  return res.headers.get('location');
}

describe('home page', () => {
  it('shows both lists, empty at first', async () => {
    const res = await fetch(base);
    const html = await res.text();

    expect(res.status).toBe(200);
    expect(html).toContain('Currently reading');
    expect(html).toContain('Finished');
    expect(html).toContain('Nothing on the go');
  });

  it('lists a reading book, then moves it to finished', async () => {
    await addBook({ title: 'Dune', author: 'Frank Herbert' });

    let html = await (await fetch(base)).text();
    expect(html).toContain('Dune');
    expect(html).toContain('Frank Herbert');
    expect(html).toContain('Mark finished');

    const { reading } = store.list();
    const finish = await fetch(`${base}/books/${reading[0].id}/finish`, form({ from: '/' }));
    expect(finish.status).toBe(303);
    expect(finish.headers.get('location')).toBe('/');

    html = await (await fetch(base)).text();
    expect(html).not.toContain('Mark finished');
    expect(html).toContain('Finished');
    expect(html).toContain('No finished books yet.');
    expect(html.indexOf('Dune')).toBeGreaterThan(html.indexOf('No finished books yet.'));
  });
});

describe('adding a book', () => {
  it('redirects to the new book page', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'spice' });
    expect(location).toMatch(/^\/books\/[\w-]+$/);

    const html = await (await fetch(base + location)).text();
    expect(html).toContain('Dune');
    expect(html).toContain('Frank Herbert');
    expect(html).toContain('spice');
  });

  it('re-shows the form with an error and the typed values when the title is blank', async () => {
    const res = await fetch(`${base}/books`, form({ title: '  ', author: 'Someone' }));
    const html = await res.text();

    expect(res.status).toBe(400);
    expect(html).toContain('A title is required.');
    expect(html).toContain('value="Someone"');
    expect(store.list().reading).toHaveLength(0);
  });
});

describe('a single book page', () => {
  it('is reachable by its own url and shows title, author and notes', async () => {
    const location = await addBook({ title: 'Dune', author: 'Frank Herbert', notes: 'The spice must flow.' });

    // The whole point of a shareable link: a cold GET with no prior state.
    const res = await fetch(base + location);
    const html = await res.text();

    expect(res.status).toBe(200);
    expect(html).toContain('<h1>Dune</h1>');
    expect(html).toContain('Frank Herbert');
    expect(html).toContain('The spice must flow.');
    expect(html).toContain('<title>Dune — Bookshelf</title>');
  });

  it('says "Unknown author" when no author was given', async () => {
    const location = await addBook({ title: 'Beowulf' });
    expect(await (await fetch(base + location)).text()).toContain('Unknown author');
  });

  it('saves notes and shows them on reload', async () => {
    const location = await addBook({ title: 'Dune' });
    const id = location.split('/').pop();

    const saved = await fetch(`${base}/books/${id}/notes`, form({ notes: 'Halfway through book two.' }));
    expect(saved.status).toBe(303);
    expect(saved.headers.get('location')).toBe(`/books/${id}?saved=1`);

    const html = await (await fetch(base + location)).text();
    expect(html).toContain('Halfway through book two.');
  });

  it('can be marked finished from its own page and comes back to it', async () => {
    const location = await addBook({ title: 'Dune' });
    const id = location.split('/').pop();

    const res = await fetch(`${base}/books/${id}/finish`, form({ from: location }));
    expect(res.headers.get('location')).toBe(location);

    const html = await (await fetch(base + location)).text();
    expect(html).toContain('Finished');
    expect(html).not.toContain('Mark finished');
  });

  it('404s on an unknown id', async () => {
    const res = await fetch(`${base}/books/deadbeef`);
    expect(res.status).toBe(404);
    expect(await res.text()).toContain('No such book');
  });
});

describe('safety', () => {
  it('escapes html in user input', async () => {
    const location = await addBook({
      title: '<script>alert(1)</script>',
      notes: '"><img src=x onerror=alert(1)>',
    });
    const html = await (await fetch(base + location)).text();

    expect(html).not.toContain('<script>alert(1)</script>');
    expect(html).not.toContain('<img src=x');
    expect(html).toContain('&lt;script&gt;');
  });

  it('ignores an off-site redirect target', async () => {
    const location = await addBook({ title: 'Dune' });
    const id = location.split('/').pop();

    const res = await fetch(`${base}/books/${id}/finish`, form({ from: 'https://evil.example/x' }));
    expect(res.headers.get('location')).toBe(location);
  });

  it('404s unknown routes', async () => {
    expect((await fetch(`${base}/nope`)).status).toBe(404);
  });
});

